interface Greeter {
  default String greet() { return "hi"; }
}
class M implements Greeter {
  @Override public String greet() { return "hello"; }
}
class Main {
  public static void main(String[] args) {
    Greeter g = new M();
    System.out.println(g.greet());
  }
}

